def existing_accounts_have_been_shown_round(apps, schema_editor):
    """The guide is for new accounts. Somebody who has used Rytivo for months
    should not be stopped by a tour of it the first time they open the app
    after this ships."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    GuideCompletion = apps.get_model('core', 'GuideCompletion')
    now = timezone.now()
    batch = []
    for user_id in User.objects.order_by().values_list('pk', flat=True).iterator(chunk_size=2000):
        batch.extend(GuideCompletion(user_id=user_id, surface=surface, completed_at=now)
                     for surface in ('ios', 'web'))
        if len(batch) >= 2000:
            GuideCompletion.objects.bulk_create(batch, ignore_conflicts=True)
            batch = []
    GuideCompletion.objects.bulk_create(batch, ignore_conflicts=True)


